// permutations returns all permutations of values as [houses]string slices.
func permutations(values []string) [][houses]string {
	var out [][houses]string
	perm := make([]string, len(values))
	used := make([]bool, len(values))
	var rec func(k int)
	rec = func(k int) {
		if k == len(values) {
			var p [houses]string
			copy(p[:], perm)
			out = append(out, p)
			return
		}
		for i, v := range values {
			if used[i] {
				continue
			}
			used[i] = true
			perm[k] = v
			rec(k + 1)
			used[i] = false
		}
	}
	rec(0)
	return out
}
