package zebra

// Solution holds the answers to the two questions of the Zebra Puzzle.
type Solution struct {
	DrinksWater string
	OwnsZebra   string
}

const houses = 5

// SolvePuzzle solves the Zebra Puzzle by backtracking over the five
// categories (color, nationality, drink, cigarette, pet), pruning any
// assignment that violates a constraint, and reports which nationality
// drinks water and which owns the zebra.
func SolvePuzzle() Solution {
	colors := []string{"red", "green", "ivory", "yellow", "blue"}
	nations := []string{"Englishman", "Spaniard", "Ukrainian", "Norwegian", "Japanese"}
	drinks := []string{"coffee", "tea", "milk", "water", "orange juice"}
	cigs := []string{"Old Gold", "Kools", "Chesterfields", "Lucky Strike", "Parliaments"}
	pets := []string{"dog", "snails", "fox", "horse", "zebra"}

	// state[category][house] holds the value assigned to that house.
	state := [5][houses]string{}

	perms := [5][][houses]string{
		permutations(colors),
		permutations(nations),
		permutations(drinks),
		permutations(cigs),
		permutations(pets),
	}

	// ok[stage] checks every constraint that involves only categories
	// assigned at or before that stage.
	ok := [5]func() bool{
		func() bool {
			// 6. The green house is immediately to the right of the ivory house.
			return greenRightOfIvory(state[0])
		},
		func() bool {
			// 2. The Englishman lives in the red house.
			// 10. The Norwegian lives in the first house.
			return englishmanInRed(state) && norwegianInFirstHouse(state)
		},
		func() bool {
			// 4. Coffee is drunk in the green house.
			// 9. Milk is drunk in the middle house.
			// 5. The Ukrainian drinks tea.
			return coffeeInGreen(state) && milkInMiddleHouse(state) && ukrainianDrinksTea(state)
		},
		func() bool {
			// 8. Kools are smoked in the yellow house.
			// 14. The Japanese smokes Parliaments.
			// 13. The Lucky Strike smoker drinks orange juice.
			return koolsInYellow(state) && japaneseSmokesParliaments(state) && luckyStrikeDrinksOJ(state)
		},
		func() bool {
			// 3. The Spaniard owns the dog.
			// 7. The Old Gold smoker owns snails.
			// 11. Chesterfields are smoked next to the house with the fox.
			// 12. Kools are smoked next to the house with the horse.
			return spaniardOwnsDog(state) && oldGoldOwnsSnails(state) &&
				chesterfieldsNextToFox(state) && koolsNextToHorse(state)
		},
	}

	solve := func(stage int) bool {
		if stage == 5 {
			return true
		}
		for _, perm := range perms[stage] {
			state[stage] = perm
			if ok[stage]() && solve(stage+1) {
				return true
			}
		}
		return false
	}

	solve(0)

	// 15. The Norwegian lives next to the blue house is implied by the
	// other constraints in the classic puzzle; report the two answers.
	var sol Solution
	for h := 0; h < houses; h++ {
		if state[2][h] == "water" {
			sol.DrinksWater = state[1][h]
		}
		if state[4][h] == "zebra" {
			sol.OwnsZebra = state[1][h]
		}
	}
	return sol
}

// permutations returns all permutations of values as [houses]string slices.
func permutations(values []string) [][houses]string {
	var out [][houses]string
	perm := make([]string, len(values))
	used := make([]bool, len(values))
	var rec func(k int)
	rec = func(k int) {
		if k == len(values) {
			var p [houses]string
			copy(p[:], perm)
			out = append(out, p)
			return
		}
		for i, v := range values {
			if used[i] {
				continue
			}
			used[i] = true
			perm[k] = v
			rec(k + 1)
			used[i] = false
		}
	}
	rec(0)
	return out
}

// index returns the house (0-based) where row holds v, or -1 if absent.
func index(row [houses]string, v string) int {
	for i, x := range row {
		if x == v {
			return i
		}
	}
	return -1
}

func greenRightOfIvory(colors [houses]string) bool {
	g := index(colors, "green")
	return g > 0 && colors[g-1] == "ivory"
}

func englishmanInRed(state [5][houses]string) bool {
	return index(state[1], "Englishman") == index(state[0], "red")
}

func norwegianInFirstHouse(state [5][houses]string) bool {
	return state[1][0] == "Norwegian"
}

func norwegianNextToBlue(state [5][houses]string) bool {
	return state[0][1] == "blue"
}

func coffeeInGreen(state [5][houses]string) bool {
